// csilEncEventRoleAssignment builds the canonical CBOR value tree for a EventRoleAssignment.
func csilEncEventRoleAssignment(csilV EventRoleAssignment) cborValue {
	csilEntries := make(cborMap, 0, 8)
	csilEntries = append(csilEntries, cborEntry{cborText("role"), cborText(csilV.Role)})
	csilEntries = append(csilEntries, cborEntry{cborText("handle"), cborText(csilV.Handle)})
	csilEntries = append(csilEntries, cborEntry{cborText("user_id"), cborText(csilV.UserId)})
	if csilV.EventId != nil {
		csilEntries = append(csilEntries, cborEntry{cborText("event_id"), cborText((*csilV.EventId))})
	}
	if csilV.SeriesId != nil {
		csilEntries = append(csilEntries, cborEntry{cborText("series_id"), cborText((*csilV.SeriesId))})
	}
	csilEntries = append(csilEntries, cborEntry{cborText("assigned_at"), csilEncTimestamp(csilV.AssignedAt)})
	csilEntries = append(csilEntries, cborEntry{cborText("display_name"), cborText(csilV.DisplayName)})
	csilEntries = append(csilEntries, cborEntry{cborText("linkkeys_domain"), cborText(csilV.LinkkeysDomain)})
	return csilEntries
}

// csilDecEventRoleAssignment reconstructs a EventRoleAssignment from a decoded CBOR value tree.
func csilDecEventRoleAssignment(csilRoot cborValue) (EventRoleAssignment, error) {
	var csilOut EventRoleAssignment
	if csilField, csilOk := cborMapGet(csilRoot, "event_id"); csilOk {
		csilVal, csilErr := (func(csilV cborValue) (EventID, error) {
			csilInner, csilErr := (cborAsText)(csilV)
			return EventID(csilInner), csilErr
		})(csilField)
		if csilErr != nil {
			return csilOut, csilErr
		}
		csilOut.EventId = &csilVal
	}
	if csilField, csilOk := cborMapGet(csilRoot, "series_id"); csilOk {
		csilVal, csilErr := (func(csilV cborValue) (EventSeriesID, error) {
			csilInner, csilErr := (cborAsText)(csilV)
			return EventSeriesID(csilInner), csilErr
		})(csilField)
		if csilErr != nil {
			return csilOut, csilErr
		}
		csilOut.SeriesId = &csilVal
	}
	{
		csilField, csilErr := cborRequire(csilRoot, "user_id")
		if csilErr != nil {
			return csilOut, csilErr
		}
		csilVal, csilErr := (func(csilV cborValue) (UserID, error) {
			csilInner, csilErr := (cborAsText)(csilV)
			return UserID(csilInner), csilErr
		})(csilField)
		if csilErr != nil {
			return csilOut, csilErr
		}
		csilOut.UserId = csilVal
	}
	{
		csilField, csilErr := cborRequire(csilRoot, "handle")
		if csilErr != nil {
			return csilOut, csilErr
		}
		csilVal, csilErr := (cborAsText)(csilField)
		if csilErr != nil {
			return csilOut, csilErr
		}
		csilOut.Handle = csilVal
	}
	{
		csilField, csilErr := cborRequire(csilRoot, "linkkeys_domain")
		if csilErr != nil {
			return csilOut, csilErr
		}
		csilVal, csilErr := (cborAsText)(csilField)
		if csilErr != nil {
			return csilOut, csilErr
		}
		csilOut.LinkkeysDomain = csilVal
	}
	{
		csilField, csilErr := cborRequire(csilRoot, "display_name")
		if csilErr != nil {
			return csilOut, csilErr
		}
		csilVal, csilErr := (cborAsText)(csilField)
		if csilErr != nil {
			return csilOut, csilErr
		}
		csilOut.DisplayName = csilVal
	}
	{
		csilField, csilErr := cborRequire(csilRoot, "role")
		if csilErr != nil {
			return csilOut, csilErr
		}
		csilVal, csilErr := (func(csilV cborValue) (EventRole, error) {
			csilInner, csilErr := (func(csilV cborValue) (string, error) {
				csilInner, csilErr := (cborAsText)(csilV)
				if csilErr != nil {
					var csilZero string
					return csilZero, csilErr
				}
				if !(csilInner == "organizer" || csilInner == "presenter") {
					var csilZero string
					return csilZero, fmt.Errorf("csil cbor: value %v is not a member of the declared enum", csilInner)
				}
				return csilInner, nil
			})(csilV)
			return EventRole(csilInner), csilErr
		})(csilField)
		if csilErr != nil {
			return csilOut, csilErr
		}
		csilOut.Role = csilVal
	}
	{
		csilField, csilErr := cborRequire(csilRoot, "assigned_at")
		if csilErr != nil {
			return csilOut, csilErr
		}
		csilVal, csilErr := (csilAsTimestamp)(csilField)
		if csilErr != nil {
			return csilOut, csilErr
		}
		csilOut.AssignedAt = csilVal
	}
	return csilOut, nil
}

